18	void unwrap(double* angles) {
19	    // Store the first original angle for difference calculations.
20	    double prev_orig = angles[0];
21	
22	    // The first angle remains unchanged.
23	    for (int i = 1; i < PULSES; i++) {
24	
25	        // Save the current original value before modifying it.
26	        double current_orig = angles[i];
27	        double diff = current_orig - prev_orig;
28	
29	        // Wrap diff into the range [-pi, pi)
30	        double dp = fmod(diff + PI, TWO_PI);
31	        if (dp < 0)
32	            dp += TWO_PI;
33	        dp -= PI;
34	
35	        // Adjust the edge case: if dp == -pi and diff > 0, set dp to pi.
36	        if (dp == -PI && diff > 0)
37	            dp = PI;
38	
39	        // The new (unwrapped) angle is the previous unwrapped angle plus dp.
40	        angles[i] = angles[i - 1] + dp;
41	
42	        // Update prev_orig to the original value before modification.
43	        prev_orig = current_orig;
44	    }
45	}
46	
47	int main(int argc, char ** argv) {
48	
49	    // Number of iterations to run
50	    const int ITER = 1;
51	
52	    // Generate random seed
53	    std::time_t seed = std::time(0);
54	    std::srand(seed);
55	    std::cout << "Rand Seed: " << seed << std::endl;
56	
57	    // Total error count
58	    int total_err_cnt = 0;
59	
60	    // Initialize all AIE graphs
61	    for(int inst=0; inst<INSTANCES; inst++) {
62	        bpGraph[inst].init();
63	    }
64	
65	    // OPEN SAR DATASET FILES
66	    float* broadcast_data_array = (float*) GMIO::malloc(PULSES*BC_ELEMENTS*sizeof(float));
67	    
68	    // Current working dir inside build/hw/aiesim/
69	    std::ifstream st_file("../../../design/test_data/gotcha_slowtime_pass1_360deg_HH.csv");
70	    if (!st_file.is_open()) {
71	        std::cerr << "Error opening st_file dataset!" << std::endl;
72	        return 1;
73	    }
74	    std::string line;
75	    int pulse_idx = 0;
76	    while (std::getline(st_file, line) && pulse_idx < PULSES) {
77	        std::stringstream ss(line);
78	        std::string value;
79	
80	        // Read each column from the line and store in respective array
81	        std::getline(ss, value, ',');
82	        broadcast_data_array[BC_ELEMENTS*pulse_idx] = std::stof(value);
83	
84	        std::getline(ss, value, ',');
85	        broadcast_data_array[BC_ELEMENTS*pulse_idx + 1] = std::stof(value);
86	
87	        std::getline(ss, value, ',');
88	        broadcast_data_array[BC_ELEMENTS*pulse_idx + 2] = std::stof(value);
89	
90	        std::getline(ss, value, ',');
91	        broadcast_data_array[BC_ELEMENTS*pulse_idx + 3] = std::stof(value);
92	
93	        pulse_idx++;
94	    }
95	
96	    cfloat* rc_array = (cfloat*) GMIO::malloc(PULSES*RC_SAMPLES*sizeof(cfloat));
97	     
98	    // Current working dir inside build/hw/aiesim/
99	    std::string rc_filename = "../../../design/test_data/gotcha_" + 
100	                              std::to_string(RC_SAMPLES) + 
101	                              "-out-of-424-rc-samples_pass1_360deg_HH.csv";
102	    std::ifstream rc_file(rc_filename);
103	    if (!rc_file.is_open()) {
104	        std::cerr << "Error opening rc_file dataset!" << std::endl;
105	        return 1;
106	    }
107	    pulse_idx = 0;
108	    while (std::getline(rc_file, line) && pulse_idx < PULSES) {
109	        std::stringstream ss(line);
110	        std::string value;
111	        int rc_samp_cnt = 0;
112	
113	        // Read each column (complex number) from the line and store in array
114	        while (std::getline(ss, value, ',') && rc_samp_cnt < RC_SAMPLES) {
115	            std::regex complex_regex(R"(([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)([+-](?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)i)");
116	            std::smatch match;
117	            std::regex_search(value, match, complex_regex);
118	
119	            float real_part = std::stof(match[1].str());
120	            float imag_part = std::stof(match[2].str());
121	
122	            // Store the complex number in the array
123	            rc_array[pulse_idx*RC_SAMPLES + rc_samp_cnt] = (cfloat) {real_part, imag_part};
124	
125	            rc_samp_cnt++;
126	        }
127	        rc_samp_cnt = 0;
128	        pulse_idx++;
129	    }
130	
131	    // AZIMUTH RESOLUTION GRID
132	    double az_res = 0;
133	    double half_az_width = 0;
134	    if (PULSES != 1) {
135	        double az_ant[PULSES];
136	        for (int i = 0; i < PULSES; i++) {
137	            // atan2(y_ant_pos / x_ant_pos)
138	            az_ant[i] = std::atan2(broadcast_data_array[BC_ELEMENTS*i+1], broadcast_data_array[BC_ELEMENTS*i]);
139	        }
140	        unwrap(az_ant);
141	        double sum_diff = 0.0;
142	        for (int i = 1; i < PULSES; i++) {
143	            sum_diff += (az_ant[i] - az_ant[i - 1]);
144	        }
145	        double mean_diff = sum_diff / (PULSES - 1);
146	        double delta_az = std::fabs(mean_diff);
147	        double min_az = *std::min_element(az_ant, az_ant + PULSES);
148	        double max_az = *std::max_element(az_ant, az_ant + PULSES);
149	        double total_az = max_az - min_az;
150	        az_res = C/(2.0*total_az*MIN_FREQ);
151	        double az_width = C/(2.0*delta_az*MIN_FREQ);
152	        half_az_width = az_width/2.0;
153	    }
154	
155	    float* xyz_px_array = (float*) GMIO::malloc(PULSES*RC_SAMPLES*sizeof(float)*3);
156	    int idx = 0;
157	    for(int pulse_idx = 0; pulse_idx < PULSES; pulse_idx++) {
158	        for(int rng_idx = 0; rng_idx < RC_SAMPLES; rng_idx++) {
159	            
160	            // X target pixels
161	            xyz_px_array[idx++] = (rng_idx-HALF_RANGE_SAMPLES)*RANGE_RES;
162	
163	            // Y target pixels
164	            xyz_px_array[idx++] = az_res*pulse_idx - half_az_width;
165	
166	            // Z target pixels
167	            xyz_px_array[idx++] = 0.0;
168	
169	            printf("xyz_px_array[%d] = {%f, %f, %f}\n", (idx-3)/3, xyz_px_array[idx-3], xyz_px_array[idx-2], xyz_px_array[idx-1]);
170	        }
171	    }
172	
173	    // Number of iteration for the AIE graphs to run
174	    for (int inst = 0; inst < INSTANCES; inst++) {
175	        bpGraph[inst].run(PULSES);
176	    }
177	
178	    // Number of target pixels for each px_demux_kern to process
179	    int px_per_demux_kern = ((PULSES*RC_SAMPLES)/AIE_SWITCHES);
180	
181	    // Loop through pipeline ITER times
182	    int inst = 0;
183	    
184	    for(int iter=0; iter<ITER; iter++) {
185	        printf("\nPERFORM BACKPROJECTION (ITER = %d) (INST = %d)\n", iter, inst);
186	
187	        // Pass in slowtime data into AI kernels
188	        bpGraph[inst].gmio_in_st.gm2aie_nb(broadcast_data_array, PULSES*BC_ELEMENTS*sizeof(float));
189	
190	        // Pass in other data into bp AI kernels
191	        for(int pulse_idx=0; pulse_idx<PULSES; pulse_idx++) {
192	
193	            bpGraph[inst].gmio_in_rc.gm2aie_nb(rc_array + pulse_idx*RC_SAMPLES, RC_SAMPLES*sizeof(cfloat));
194	            for (int sw_id=0; sw_id<AIE_SWITCHES; sw_id++) {
195	                bpGraph[inst].bpCluster[sw_id].gmio_in_xyz_px.gm2aie_nb(xyz_px_array + sw_id*px_per_demux_kern*3, px_per_demux_kern*sizeof(float)*3);
196	            }
